}

/**
 * @method
 * @name scwin.fnGetCookieComCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnGetCookieComCode = async function () {
    /* sdd-asis-lifecycle:begin fnGetCookieComCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const cookiesStr = scwin.fnGetCookie('krxComp');
    let totalArray;
    let newVal = "";
    let newComNm = "";
    if (cookiesStr != null) {
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    if (totalArray) {
        for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
            const sCookieTemp = totalArray[i].split(",");
            if (i == 0) {
                newVal = newVal + sCookieTemp[1];
            } else {
                newVal = newVal + "," + sCookieTemp[1];
            }
            newComNm = sCookieTemp[2];
        }
    } else {
        await $c.win.alert("최근 검색한 회사가 없습니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", newVal);
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


